sys_script_include.script:
var QuizHelper = Class.create();
QuizHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getRandom: function() {
        var questionGr = new GlideRecord("x_1397649_quiz_app_question");

        var agg = new GlideAggregate("x_1397649_quiz_app_question");
        agg.addAggregate("COUNT");
        agg.query();
        var total = 0;

        if (agg.next()) {
            total = parseInt(agg.getAggregate("COUNT"), 10);
        }

        if (total === 0) {
            return JSON.stringify({
                error: "No questions available"
            });
        }

        var randomIndex = Math.floor(Math.random() * total);

        // var random = Math.floor(Math.random() * 10) + 1;
        // questionGr.addQuery("u_id", random);

        questionGr.chooseWindow(randomIndex, randomIndex + 1);
        questionGr.query();

        if (questionGr.next()) {
            var question = questionGr.getValue("question");

            var answerGr = new GlideRecord("x_1397649_quiz_app_answer");
            answerGr.addQuery("question", questionGr.getUniqueValue());
            answerGr.query();
            var answers = [];
            while (answerGr.next()) {
                answers.push({
                    "answer": answerGr.getValue("answer"),
                    "correct": answerGr.getValue("correct") == "1" ? 1 : 0
                });
            }

            return JSON.stringify({
                "question": question,
                "answers": answers
            });
        }
    },

    getRandomWithAnswer: function() {
        var questions = [];

        var ga = new GlideAggregate('x_1397649_quiz_app_answer');
        ga.addAggregate('COUNT', 'question');
        ga.groupBy('question');
        ga.addHaving('COUNT', '>=', 4);
        ga.query();

        while (ga.next()) {
            questions.push(ga.getValue('question'));
        }

        if (questions.length === 0) {
            return JSON.stringify({
                error: "No questions with at least 4 answers"
            });
        }


        var randomIndex = Math.floor(Math.random() * questions.length);
        var randomQuestionId = questions[randomIndex];
        var questionGr = new GlideRecord("x_1397649_quiz_app_question");
        if (questionGr.get(randomQuestionId)) {
            var question = questionGr.getValue("question");

            var answerGr = new GlideRecord("x_1397649_quiz_app_answer");
            answerGr.addQuery("question", randomQuestionId);
            answerGr.query();

            var answers = [];

            while (answerGr.next()) {
                answers.push({
                    "answer": answerGr.getValue("answer"),
                    "correct": answerGr.getValue("correct") === "1" ? 1 : 0
                });
            }

            return JSON.stringify({
                "question": question,
                "answers": answers
            });
        }

        return JSON.stringify({
            error: "Question not found"
        });
    },

	isDarkMode: function() {
		return gs.getProperty('x_1397649_quiz_app.dark_mode', 'false');
	},

    hasCorrect: function() {
        var sys_id = this.getParameter("sysparm_sys_id");
        var question = this.getParameter("sysparm_question");

        var correctCount = new GlideAggregate("x_1397649_quiz_app_answer");
        correctCount.addQuery("question", question);
        correctCount.addQuery("sys_id", "!=", sys_id);
        correctCount.addQuery("correct", 1);
        correctCount.addAggregate("COUNT");
        correctCount.query();
        if (correctCount.next()) {
            return parseInt(correctCount.getAggregate("COUNT")) > 0;
        }
    },

    getAnswersNum: function() {
        var question = this.getParameter("sysparm_question");
        var count = new GlideAggregate("x_1397649_quiz_app_answer");
        count.addAggregate("COUNT");
        count.addQuery("question", question);
        count.query();
        if (count.next()) {
            return count.getAggregate("COUNT");
        }
    },

    type: 'QuizHelper'
});
